CREATE TABLE IF NOT EXISTS spot_checks (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, area TEXT NOT NULL, side TEXT, answer TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wellness (date TEXT PRIMARY KEY, sleep_min INTEGER, sleep_base INTEGER, hrv INTEGER, hrv_base INTEGER, rhr INTEGER, source TEXT, created_at TEXT NOT NULL);
ALTER TABLE runs ADD COLUMN enjoyment REAL;
